-- ----------------------------
-- 心理测评模块：内置量表数据（4 个核心量表）
-- 题目均按标准量表原文配置，仅限学术用途
-- 量表来源：PHQ-9/GAD-7/PSS-10/PSQI
-- 评分说明：scoring_config 为 JSON，供 AssessmentScoringService 计分引擎消费
--   - reverseScoreQuestionIndexes：反向计分题（0 索引），score = reverseMaxScore - score
--   - dimensions：维度归组，每个维度含 questionIndexes（0 索引）与可选 scoreMap（将原始分和映射为 0-3）
--   - totalFromDimensions：true 表示总分=各维度得分之和（PSQI 用），false 表示总分=各题得分之和
--   - levels：等级阈值闭区间 [min, max]
--   - riskQuestionIndexes/riskScoreThreshold：风险题与阈值
-- ----------------------------
use mental_health_assistant;

-- PHQ-9 抑郁症筛查量表
INSERT INTO `assessment_scale` (`code`, `name`, `category`, `description`, `question_count`, `estimated_minutes`, `scoring_config`, `enabled`, `sort_order`)
VALUES ('PHQ-9', 'PHQ-9 抑郁症筛查量表', 'EMOTION',
        'PHQ-9（Patient Health Questionnaire-9）是国际通用的抑郁症状筛查量表，共 9 题，约 2 分钟完成。量表来源：Spitzer RL 等（1999）。本测评结果仅供参考，不构成医疗诊断。',
        9, 2,
        CAST('{"questions":[{"index":0,"text":"做事时提不起劲或没有兴趣","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":1,"text":"感到心情低落、沮丧或绝望","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":2,"text":"入睡困难、睡不安稳或睡眠过多","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":3,"text":"感觉疲倦或没有活力","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":4,"text":"食欲不振或吃太多","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":5,"text":"觉得自己很糟、很失败，或让自己或家人失望","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":6,"text":"对事物专注有困难（如阅读报纸或看电视时）","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":7,"text":"动作或说话速度缓慢到别人已察觉，或相反地烦躁或坐立不安","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":8,"text":"有不如死掉或用某种方式伤害自己的念头","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]}],"reverseScoreQuestionIndexes":[],"reverseMaxScore":0,"totalFromDimensions":false,"dimensions":[],"levels":[{"level":"NORMAL","min":0,"max":4,"description":"当前情绪状态处于正常范围，未提示明显抑郁症状","suggestion":"保持规律作息与适度运动，维持良好的社交活动"},{"level":"MILD","min":5,"max":9,"description":"可能存在轻度抑郁情绪，建议关注近期状态","suggestion":"尝试规律作息、适度运动、向信任的人倾诉；持续关注情绪变化"},{"level":"MODERATE","min":10,"max":14,"description":"可能存在中度抑郁情绪，建议进一步评估","suggestion":"建议寻求专业心理咨询帮助，进行进一步评估与支持"},{"level":"SEVERE","min":15,"max":27,"description":"可能存在较严重的抑郁情绪，请予以重视","suggestion":"强烈建议尽快前往正规医院心理科或精神科就诊，接受专业评估"}],"riskQuestionIndexes":[8],"riskScoreThreshold":1,"categoryAdvice":["规律作息，保证充足睡眠","适度运动，如散步、慢跑","向家人朋友倾诉感受","尝试正念呼吸练习","减少咖啡因与酒精摄入"]}' AS JSON),
        1, 10);

-- GAD-7 焦虑症筛查量表
INSERT INTO `assessment_scale` (`code`, `name`, `category`, `description`, `question_count`, `estimated_minutes`, `scoring_config`, `enabled`, `sort_order`)
VALUES ('GAD-7', 'GAD-7 焦虑症筛查量表', 'EMOTION',
        'GAD-7（Generalized Anxiety Disorder-7）是国际通用的焦虑症状筛查量表，共 7 题，约 2 分钟完成。量表来源：Spitzer RL 等（2006）。本测评结果仅供参考，不构成医疗诊断。',
        7, 2,
        CAST('{"questions":[{"index":0,"text":"感到紧张、焦虑或急切","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":1,"text":"不能够停止或控制担忧","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":2,"text":"对各种各样的事情担忧过多","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":3,"text":"很难放松下来","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":4,"text":"由于不安而无法静坐","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":5,"text":"变得容易烦恼或易被激怒","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]},{"index":6,"text":"感到好像有什么可怕的事情会发生","options":[{"label":"完全不会","score":0},{"label":"好几天","score":1},{"label":"一半以上天数","score":2},{"label":"几乎每天","score":3}]}],"reverseScoreQuestionIndexes":[],"reverseMaxScore":0,"totalFromDimensions":false,"dimensions":[],"levels":[{"level":"NORMAL","min":0,"max":4,"description":"当前焦虑水平处于正常范围","suggestion":"保持放松练习与规律生活，维持身心健康"},{"level":"MILD","min":5,"max":9,"description":"可能存在轻度焦虑情绪","suggestion":"尝试腹式呼吸、正念冥想等放松训练；适度运动"},{"level":"MODERATE","min":10,"max":14,"description":"可能存在中度焦虑情绪，建议进一步评估","suggestion":"建议寻求专业心理咨询，学习系统的焦虑应对策略"},{"level":"SEVERE","min":15,"max":21,"description":"可能存在较严重的焦虑情绪，请予以重视","suggestion":"建议尽快前往正规医院心理科就诊，接受专业评估"}],"riskQuestionIndexes":[],"riskScoreThreshold":0,"categoryAdvice":["腹式呼吸与深呼吸练习","正念冥想放松训练","规律有氧运动","减少咖啡因摄入","合理安排时间，避免过度压力"]}' AS JSON),
        1, 20);

-- PSS-10 压力知觉量表
INSERT INTO `assessment_scale` (`code`, `name`, `category`, `description`, `question_count`, `estimated_minutes`, `scoring_config`, `enabled`, `sort_order`)
VALUES ('PSS-10', 'PSS-10 压力知觉量表', 'STRESS',
        'PSS-10（Perceived Stress Scale-10）由 Cohen 等人编制，用于评估近一个月感受到的压力水平，共 10 题，约 3 分钟完成。第 4/5/7/8 题为反向计分。量表来源：Cohen S 等（1983）。本测评结果仅供参考，不构成医疗诊断。',
        10, 3,
        CAST('{"questions":[{"index":0,"text":"因发生意料之外的事情而感到心烦","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]},{"index":1,"text":"感到无法控制生活中重要的事情","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]},{"index":2,"text":"感到紧张和有压力","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]},{"index":3,"text":"能够成功地处理恼人的生活麻烦","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]},{"index":4,"text":"感到自己能够有效地应对生活中发生的重要变化","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]},{"index":5,"text":"对自己处理个人问题的能力感到有信心","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]},{"index":6,"text":"感到事情按自己心意发展","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]},{"index":7,"text":"发现自己无法处理所有必须做的事情","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]},{"index":8,"text":"能够控制生活中令人愤怒的事情","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]},{"index":9,"text":"感到困难积压太多以至于无法克服","options":[{"label":"从不","score":0},{"label":"几乎从不","score":1},{"label":"有时","score":2},{"label":"经常","score":3},{"label":"总是","score":4}]}],"reverseScoreQuestionIndexes":[3,4,6,7],"reverseMaxScore":4,"totalFromDimensions":false,"dimensions":[{"name":"压力感","questionIndexes":[0,1,2,5,8,9]},{"name":"应对感","questionIndexes":[3,4,6,7]}],"levels":[{"level":"NORMAL","min":0,"max":13,"description":"当前感知到的压力处于较低水平，应对资源较为充足","suggestion":"保持良好的压力管理习惯，维持工作与生活平衡"},{"level":"MILD","min":14,"max":26,"description":"存在中等水平的压力感知","suggestion":"建议增加放松活动，合理规划任务，寻求社交支持"},{"level":"SEVERE","min":27,"max":40,"description":"感知到的压力处于较高水平，请予以关注","suggestion":"建议学习系统的压力管理技能，必要时寻求专业心理支持"}],"riskQuestionIndexes":[],"riskScoreThreshold":0,"categoryAdvice":["合理规划时间，拆解任务","规律运动释放压力","保持充足睡眠","向信任的人倾诉","尝试正念与放松训练"]}' AS JSON),
        1, 30);

-- PSQI 睡眠质量量表（简化版：7 个核心成分题，每题 0-3，总分 0-21）
INSERT INTO `assessment_scale` (`code`, `name`, `category`, `description`, `question_count`, `estimated_minutes`, `scoring_config`, `enabled`, `sort_order`)
VALUES ('PSQI', 'PSQI 睡眠质量量表', 'SLEEP',
        'PSQI（Pittsburgh Sleep Quality Index）由 Buysse 等人编制，用于评估近一个月的睡眠质量。本量表为学术演示简化版，选取 7 个核心成分各 1 道代表性题目，每题 0-3 分，总分 0-21 分，分数越高提示睡眠质量越差。量表来源：Buysse DJ 等（1989）。本测评结果仅供参考，不构成医疗诊断。',
        7, 3,
        CAST('{"questions":[{"index":0,"text":"近一个月，你对自己整体睡眠质量的评价","options":[{"label":"很好","score":0},{"label":"较好","score":1},{"label":"较差","score":2},{"label":"很差","score":3}]},{"index":1,"text":"近一个月，你从上床到入睡通常需要多长时间","options":[{"label":"15分钟以内","score":0},{"label":"16-30分钟","score":1},{"label":"31-60分钟","score":2},{"label":"60分钟以上","score":3}]},{"index":2,"text":"近一个月，你每晚实际睡眠时间大约是","options":[{"label":"7小时以上","score":0},{"label":"6-7小时","score":1},{"label":"5-6小时","score":2},{"label":"不足5小时","score":3}]},{"index":3,"text":"近一个月，你睡眠效率（实际睡眠时间/在床时间）如何","options":[{"label":"85%以上","score":0},{"label":"75%-85%","score":1},{"label":"65%-75%","score":2},{"label":"65%以下","score":3}]},{"index":4,"text":"近一个月，你是否因夜间易醒或早醒而影响睡眠","options":[{"label":"没有","score":0},{"label":"偶尔","score":1},{"label":"经常","score":2},{"label":"几乎每天","score":3}]},{"index":5,"text":"近一个月，你是否使用催眠药物帮助睡眠","options":[{"label":"没有","score":0},{"label":"偶尔","score":1},{"label":"经常","score":2},{"label":"几乎每天","score":3}]},{"index":6,"text":"近一个月，你在白天感到困倦或做事精力不足的程度","options":[{"label":"没有","score":0},{"label":"偶尔","score":1},{"label":"经常","score":2},{"label":"几乎每天","score":3}]}],"reverseScoreQuestionIndexes":[],"reverseMaxScore":0,"totalFromDimensions":true,"dimensions":[{"name":"主观睡眠质量","questionIndexes":[0]},{"name":"入睡时间","questionIndexes":[1]},{"name":"睡眠时长","questionIndexes":[2]},{"name":"睡眠效率","questionIndexes":[3]},{"name":"睡眠障碍","questionIndexes":[4]},{"name":"催眠药物","questionIndexes":[5]},{"name":"日间功能障碍","questionIndexes":[6]}],"levels":[{"level":"NORMAL","min":0,"max":5,"description":"当前睡眠质量良好，未提示明显睡眠问题","suggestion":"保持规律的作息与良好的睡眠环境"},{"level":"MILD","min":6,"max":10,"description":"可能存在轻度睡眠问题","suggestion":"建议改善睡眠环境，保持规律作息，避免睡前使用电子产品"},{"level":"MODERATE","min":11,"max":15,"description":"可能存在中度睡眠问题，建议关注","suggestion":"建议调整生活方式，必要时寻求专业帮助改善睡眠"},{"level":"SEVERE","min":16,"max":21,"description":"可能存在较严重的睡眠问题，请予以重视","suggestion":"建议前往正规医院睡眠门诊或心理科就诊，接受专业评估"}],"riskQuestionIndexes":[],"riskScoreThreshold":0,"categoryAdvice":["保持规律作息，固定就寝与起床时间","营造安静舒适的睡眠环境","睡前避免使用手机等电子产品","避免睡前饮用咖啡因与酒精","白天适度运动，睡前可做放松练习"]}' AS JSON),
        1, 40);

