-- SCL-90 症状自评量表
INSERT INTO `assessment_scale` (`code`, `name`, `category`, `description`, `question_count`, `estimated_minutes`, `scoring_config`, `enabled`, `sort_order`)
VALUES ('SCL-90', 'SCL-90 症状自评量表', 'EMOTION',
        'SCL-90（Symptom Checklist 90）是世界上最著名的心理健康测试量表之一，共 94 题（标准简化版），涵盖 10 个症状因子（躯体化、强迫症状、人际关系敏感、抑郁、焦虑、敌对、恐怖、偏执、精神病性、其他），约 8-10 分钟完成。量表来源：Derogatis LR（1973）。本测评结果仅供参考，不构成医疗诊断。',
        94, 10,
