INSERT INTO `assessment_scale` (`code`, `name`, `category`, `description`, `question_count`, `estimated_minutes`, `scoring_config`, `enabled`, `sort_order`)
VALUES ('MBTI', 'MBTI 人格测试（简化版）', 'PERSONALITY',
        'MBTI（Myers-Briggs Type Indicator）是世界上最流行的人格测试工具，本系统提供简化版 20 题测试，约 5 分钟完成。完整版 MBTI 有 93 题。量表来源：Myers & Briggs Foundation。本测评结果仅供参考，不构成心理诊断。',
        20, 5,
        CAST('{"scoringMode":"polarity","questions":[{"index":0,"text":"在社交聚会中，我通常是...","options":[{"label":"主动与很多人交谈","score":1,"polarity":"E"},{"label":"只和少数熟悉的人交谈","score":0,"polarity":"I"}]},{"index":1,"text":"周末结束后，我通常感觉...","options":[{"label":"精力充沛，期待新的一周","score":1,"polarity":"E"},{"label":"疲惫，需要独处恢复","score":0,"polarity":"I"}]},{"index":2,"text":"思考问题时，我更倾向于...","options":[{"label":"边想边说，与人讨论","score":1,"polarity":"E"},{"label":"独自思考，想清楚再表达","score":0,"polarity":"I"}]},{"index":3,"text":"在新环境中，我通常...","options":[{"label":"很快融入并结识新朋友","score":1,"polarity":"E"},{"label":"先观察，慢慢适应","score":0,"polarity":"I"}]},{"index":4,"text":"我觉得被很多人关注是...","options":[{"label":"愉快的事情","score":1,"polarity":"E"},{"label":"让人紧张的事情","score":0,"polarity":"I"}]},{"index":5,"text":"我更关注...","options":[{"label":"眼前的现实和具体细节","score":1,"polarity":"S"},{"label":"未来的可能性和整体趋势","score":0,"polarity":"N"}]},{"index":6,"text":"学习新知识时，我偏好...","options":[{"label":"循序渐进，从基础到复杂","score":1,"polarity":"S"},{"label":"先建立整体框架，再填充细节","score":0,"polarity":"N"}]},{"index":7,"text":"描述一件事时，我倾向于...","options":[{"label":"具体、写实、注重事实","score":1,"polarity":"S"},{"label":"抽象、比喻、注重寓意","score":0,"polarity":"N"}]},{"index":8,"text":"我更相信...","options":[{"label":"亲身经历和眼见为实","score":1,"polarity":"S"},{"label":"直觉和灵感","score":0,"polarity":"N"}]},{"index":9,"text":"面对一个新问题，我首先...","options":[{"label":"回忆以往类似经验","score":1,"polarity":"S"},{"label":"思考可能有哪些新解法","score":0,"polarity":"N"}]},{"index":10,"text":"做决定时，我更依赖...","options":[{"label":"逻辑分析和客观事实","score":1,"polarity":"T"},{"label":"价值观和他人感受","score":0,"polarity":"F"}]},{"index":11,"text":"朋友遇到困难来找我，我会...","options":[{"label":"帮他分析问题和解决办法","score":1,"polarity":"T"},{"label":"先共情倾听，给予情感支持","score":0,"polarity":"F"}]},{"index":12,"text":"批评别人时，我倾向于...","options":[{"label":"直接指出问题所在","score":1,"polarity":"T"},{"label":"委婉表达，顾及对方感受","score":0,"polarity":"F"}]},{"index":13,"text":"我认为公平应该是...","options":[{"label":"人人平等，规则面前无例外","score":1,"polarity":"T"},{"label":"因人而异，考虑具体情况","score":0,"polarity":"F"}]},{"index":14,"text":"完成任务时，我更看重...","options":[{"label":"高效和正确","score":1,"polarity":"T"},{"label":"和谐和协作","score":0,"polarity":"F"}]},{"index":15,"text":"我的生活通常是...","options":[{"label":"有计划、有条理的","score":1,"polarity":"J"},{"label":"灵活随性、随机应变的","score":0,"polarity":"P"}]},{"index":16,"text":"外出旅行时，我偏好...","options":[{"label":"详细规划好行程","score":1,"polarity":"J"},{"label":"走到哪算哪，享受意外","score":0,"polarity":"P"}]},{"index":17,"text":"面对截止日期，我通常...","options":[{"label":"提前完成，避免临时抱佛脚","score":1,"polarity":"J"},{"label":"最后几天集中冲刺","score":0,"polarity":"P"}]},{"index":18,"text":"我的桌面或书桌通常是...","options":[{"label":"整洁有序","score":1,"polarity":"J"},{"label":"看似杂乱但我知道东西在哪","score":0,"polarity":"P"}]},{"index":19,"text":"对于待办事项，我习惯...","options":[{"label":"列清单，逐项打勾","score":1,"polarity":"J"},{"label":"记在脑子里，需要时自然想起","score":0,"polarity":"P"}]}],"reverseScoreQuestionIndexes":[],"reverseMaxScore":0,"totalFromDimensions":false,"dimensions":[{"name":"外向-内向","questionIndexes":[0,1,2,3,4]},{"name":"感觉-直觉","questionIndexes":[5,6,7,8,9]},{"name":"思考-情感","questionIndexes":[10,11,12,13,14]},{"name":"判断-感知","questionIndexes":[15,16,17,18,19]}],"levels":[{"level":"ISTJ","min":0,"max":0,"description":"安静、严肃、通过全面和可靠获得成功。注重实际，实事求是，现实。","suggestion":"你的踏实可靠是宝贵品质，尝试在坚持原则的同时也适当接受变化"},{"level":"ISFJ","min":0,"max":0,"description":"安静、友好、有责任感和良知。坚定地致力于完成他们的义务。","suggestion":"你的体贴入微让周围人感到温暖，记得也照顾好自己的需求"},{"level":"INFJ","min":0,"max":0,"description":"坚持原则、富有洞察力。寻求思想、关系和物质财产的意义。","suggestion":"你的理想主义和洞察力是独特优势，注意不要过度自我消耗"},{"level":"INTJ","min":0,"max":0,"description":"有创造力、有战略眼光，能制定长远计划。独立自主，不轻易动摇。","suggestion":"你的独立思考和战略眼光令人敬佩，尝试更多倾听他人的意见"},{"level":"ISTP","min":0,"max":0,"description":"宽容、灵活。是冷静的观察者，直到出现问题才会行动。","suggestion":"你的冷静和动手能力很强，尝试在观察之后也主动表达自己"},{"level":"ISFP","min":0,"max":0,"description":"安静、敏感、和善。享受当下。","suggestion":"你的温柔和艺术气质让世界更美，相信自己的直觉和感受"},{"level":"INFP","min":0,"max":0,"description":"理想主义、忠于自己的价值观。追求意义和真实。","suggestion":"你的共情和理想主义是珍贵品质，记得在照顾他人时也照顾自己"},{"level":"INTP","min":0,"max":0,"description":"对任何感兴趣的事物都寻求逻辑解释。喜欢理论和抽象概念。","suggestion":"你的逻辑思维和求知欲令人赞叹，尝试把想法更多地付诸行动"},{"level":"ESTP","min":0,"max":0,"description":"灵活、宽容。务实，专注于即时结果。","suggestion":"你的行动力和适应力很强，尝试在行动前也思考长远影响"},{"level":"ESFP","min":0,"max":0,"description":"外向、友好、接受力强。热爱生活、人类和物质享受。","suggestion":"你的热情感染力让人快乐，也记得给自己留出安静的时间"},{"level":"ENFP","min":0,"max":0,"description":"热情洋溢、富有想象力。认为生活充满可能性。","suggestion":"你的创造力和热情是宝贵财富，尝试在追逐新想法时也保持专注"},{"level":"ENTP","min":0,"max":0,"description":"反应快、聪明、擅长很多事情。不喜欢例行公事。","suggestion":"你的思维敏捷和辩论能力令人印象深刻，注意不要为了争论而争论"},{"level":"ESTJ","min":0,"max":0,"description":"实际、注重现实，注重事实。果断，迅速做出决定。","suggestion":"你的组织能力和执行力很强，尝试在坚持规则时也灵活变通"},{"level":"ESFJ","min":0,"max":0,"description":"热心肠、有责任心、合作。希望周遭温馨和睦。","suggestion":"你的热情和关怀让团队更团结，记得也给自己一些独处时间"},{"level":"ENFJ","min":0,"max":0,"description":"热情、为他人着想、有感染力。能够很好地带领团队。","suggestion":"你的领导力和同理心让人信服，注意不要过度承担他人的责任"},{"level":"ENTJ","min":0,"max":0,"description":"坦诚、果断，天生的领导者。能够制定清晰的目标和计划。","suggestion":"你的决断和战略能力很强，尝试在指挥时也更多授权和倾听"}],"riskQuestionIndexes":[],"riskScoreThreshold":0,"categoryAdvice":["了解自己的人格特质，发挥优势","关注自己的盲区，持续成长","接受人与人之间的差异","在不同情境下灵活调整自己"]}' AS JSON),
        1, 40);
